1	import { Suspense } from "react";
2	import { headers } from "next/headers";
3	import { db } from "@/lib/db";
4	import { requireUser } from "@/lib/auth";
5	import { clientIp } from "@/lib/rate-limit";
6	import { hashIp } from "@/lib/coupon-order";
7	import { firstMonthFreeEligible, firstMonthFreeEnabled, firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
8	import { getSettingBool } from "@/lib/settings";
9	import { annualDiscountPct } from "@/lib/annual-discount";
10	import { extraDiskPerGbCents } from "@/lib/disk-expand";
11	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
12	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
13	import { VPS_TERMS, vpsTermPriceCents, termPriceCents, termDiscountPct } from "@/lib/billing-terms";
14	import { planIntroMonthlyCents } from "@/lib/intro-pricing";
15	import { regionsFrom, defaultRegionKey, appSpriteKey, gameArt } from "@/lib/nx/catalog";
16	import { countryFromHeaders } from "@/lib/geo-currency";
17	import { countryFromRequestIp } from "@/lib/geo-ip";
18	import { GAME_DISPLAY, GAME_GENRES, HOSTNAME_CONNECT_FAMILIES, type GameFamily } from "@/lib/games";
19	import { GAME_CONFIG_SCHEMAS } from "@/lib/game-config";
20	import { GAME_FAMILIES } from "@/lib/games";
21	import { stripeConfigured } from "@/lib/stripe";
22	import { paypalConfigured } from "@/lib/paypal";
23	import { coinbaseConfigured } from "@/lib/coinbase-commerce";
24	import { DeployView } from "@/components/nx/DeployView";
25	import type { AddonOption, EmailPlanOption, GameFamilyOption, HostingPlanOption, OsOption, PlanOption, TermOption } from "@/components/nx/order-types";
26	
27	/* Data for the VPS deploy wizard.
28	 *
29	 * The one rule this file exists to keep: every number the wizard can display is
30	 * computed HERE, by the same functions that charge the card, and handed down
31	 * already worked out. The view prints; it never multiplies.
32	 *
33	 * `effectiveMonthlyCents` is built as a plan x term MATRIX rather than sent as a
34	 * rate plus a discount percent. Sending the percent would mean the browser does
35	 * `rate * (1 - pct)` — a second pricing formula, and the one that is on screen
36	 * when the customer decides. Terms are few and plans are few, so the matrix is
37	 * cheap and it cannot drift from `vpsTermPriceCents`.
38	 */
39	
40	export const dynamic = "force-dynamic";
41	
42	/* Icon per image, keyed off the platform's own `family` value rather than
43	   sniffing the display name. Control panels and applications have families too
44	   (cpanel, plesk, docker, ...), so one map serves all three tabs. */
45	const ICON_BY_FAMILY: Record<string, string> = {
46	  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
47	  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
48	  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
49	  mysql: "mysql", postgres: "postgres", redis: "redis",
50	  cpanel: "gear2", plesk: "gear2", webmin: "sliders", hestiacp: "sliders",
51	  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
52	};
53	function osIcon(family: string, category: string): string {
54	  return ICON_BY_FAMILY[family?.toLowerCase()]
55	    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
56	}
57	
58	/* The plan-card promo badge's percent — the REAL gap between the intro monthly
59	 * rate and the regular monthly rate, so "X% off" can never show a number a
60	 * plan doesn't actually carry. Computed here (once, server-side) rather than
61	 * in the card component, same discipline as every other price on this page:
62	 * the view prints, it does not work anything out. Null (no badge) unless
63	 * `introCents` is a genuine, positive discount off `regularCents`. */
64	function introBadgePercent(regularCents: number, introCents: number | null): number | null {
65	  if (introCents == null || regularCents <= 0 || introCents >= regularCents) return null;
66	  return Math.max(1, Math.min(99, Math.round((1 - introCents / regularCents) * 100)));
67	}
68	
69	export default async function NxDeployPage() {
70	  const user = await requireUser();
71	
72	  // Exit-intent 25%-off popup eligibility (Feature: EXIT25). "First-time
73	  // customer" is the codebase's own established predicate for exactly this
74	  // kind of gate — zero non-free `Server` rows — already enforced identically
75	  // by `firstTimeOnly` coupon checks in lib/order.ts and
76	  // lib/coupon-redemption.ts. Resolved HERE, server-side, and threaded down as
77	  // a plain boolean prop: the deploy page is already a server component
78	  // reading `user`, so there is no reason to let the client decide something
79	  // this consequential on its own.
80	  const [isFirstTimeCustomer, exitIntentEnabled] = await Promise.all([
81	    db.server.count({ where: { userId: user.id, isFree: false } }).then((n) => n === 0),
82	    getSettingBool("exit_intent_enabled", true),
83	  ]);
84	
85	  // Real, per-customer eligibility for the first-month-free hosting promo —
86	  // NOT a display detail, the exact same advisory pre-check
87	  // lib/actions-hosting.ts runs before the atomic claim at charge time. The
88	  // wizard's hosting/email price was a flat, precomputed matrix with zero
89	  // per-user awareness (deliberately: "so there is no round-trip to make"),
90	  // which is why the promo's own plan-card badge ("First month free") and
91	  // the wizard's actual total disagreed — the matrix could not have known
92	  // whether THIS customer still qualifies. One extra check here, resolved
93	  // alongside the rest of this page's own data fetching.
94	  const hdrs = await headers();
95	  const hostingPromoIpHash = hashIp(clientIp(hdrs), process.env.AUTH_SECRET ?? "nxeon") || null;
96	  // Same "real signal, real fallback" resolution the display-currency path
97	  // already uses (lib/currency-display.ts) — a CDN/proxy country header first,
98	  // else the bundled geoip-lite dataset off the client IP, "" (falsy) if
99	  // neither resolves. Feeds `defaultRegionKey` below so a fresh order seeds
100	  // the region actually closest to this visitor rather than an arbitrary one.
101	  const visitorCountry = countryFromHeaders(hdrs) || countryFromRequestIp(hdrs) || null;
102	  const hostingPromoEligible =
103	    firstMonthFreeAppliesTo("HOSTING") &&
104	    (await firstMonthFreeEnabled()) &&
105	    (await firstMonthFreeEligible(user.id, hostingPromoIpHash));
106	
107	  const [plans, oses, nodes, gamePlans, hostingPlans, emailPlans, annualPct, diskPerGbCents, ipCents, backupCents] = await Promise.all([
108	    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
109	    /* All three categories — the design's Server settings panel has a tab per
110	       category (Operating system / Control panels / Applications), which is
111	       exactly what ImageCategory already distinguishes. They are separated in
112	       the VIEW, not filtered out here: a game-server image is a real thing you
113	       can deploy, it just is not an answer to "pick an operating system". */
114	    /* Game images are EXCLUDED from the VPS wizard. They are real deployable
115	       images, but Nxeon sells game servers as their own product with their own
116	       plans, panel and pricing — offering "Minecraft Server" as a VPS
117	       application sells the same thing twice, at the wrong price, without the
118	       game panel. Identified by `family` against the platform's own
119	       GAME_FAMILIES registry rather than by matching "... Server" in a name. */
120	    db.osTemplate.findMany({
121	      where: { active: true, NOT: { family: { in: [...GAME_FAMILIES] } } },
122	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
123	    }),
124	    // enabled only — a disabled node is not a place we can provision. `orderBy`
125	    // makes this deterministic: without one, Postgres may return rows in any
126	    // order, and `regionsFrom` used to build the region picker straight off
127	    // that order — so "region #0", the default a fresh order seeded, could
128	    // silently change between requests. `regionsFrom` now sorts its own
129	    // output too (belt and suspenders), but the query itself should not rely
130	    // on incidental ordering either.
131	    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true }, orderBy: { id: "asc" } }),
132	    // "from" prices for the service tiles — the cheapest live plan of each kind,
133	    // read from the same tables the order path prices against.
134	    // Every active tier: the wizard groups them into families itself, so one
135	    // query serves both the "from" price on the tiles and the tier picker.
136	    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
137	    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
138	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
139	    annualDiscountPct(),
140	    extraDiskPerGbCents(),
141	    dedicatedIpMonthlyCents(),
142	    backupPlusMonthlyCents(),
143	  ]);
144	
145	  /* The monthly term is the reference rate the cards show by default; the wizard
146	     re-reads this matrix when the customer changes term. Priced through
147	     `vpsTermPriceCents`, the same helper `orderQuote` uses. */
148	  const priceMatrix: Record<string, Record<number, number>> = {};
149	  for (const p of plans) {
150	    priceMatrix[p.id] = {};
151	    for (const t of VPS_TERMS) {
152	      // term total / months = the effective monthly rate at that term
153	      priceMatrix[p.id][t.months] = Math.round(
154	        vpsTermPriceCents(p.priceCents, t.months, annualPct) / t.months
155	      );
156	    }
157	  }
158	
159	  /* "Recommended" is the middle of the ladder, not the most expensive — the
160	     default has to be a defensible choice, not an upsell. */
161	  const recommendedId = plans.length ? plans[Math.floor((plans.length - 1) / 2)].id : null;
162	
163	  const planOptions: PlanOption[] = plans.map((p) => ({
164	    id: p.id,
165	    slug: p.slug,
166	    name: p.name,
167	    cpuCores: p.cpuCores,
168	    ramMB: p.ramMB,
169	    diskGB: p.diskGB,
170	    bandwidthTB: p.bandwidthTB,
171	    monthlyCents: p.priceCents,
172	    effectiveMonthlyCents: priceMatrix[p.id][1],
173	    introMonthlyCents: p.introPriceCents ?? null,
174	    introRenewalMonthlyCents: p.introPriceCents ? p.priceCents : null,
175	    introPercent: introBadgePercent(p.priceCents, planIntroMonthlyCents(p)),
176	    recommended: p.id === recommendedId,
177	  }));
178	
179	  const osOptions: OsOption[] = oses.map((o) => ({
180	    id: o.id,
181	    name: o.name,
182	    version: o.version ?? "",
183	    icon: osIcon(o.family, o.category),
184	    category: o.category,
185	    family: o.family,
186	    spriteKey: o.category === "PLAIN_OS" ? null : appSpriteKey(o.name),
187	  }));
188	
189	  const termOptions: TermOption[] = VPS_TERMS.map((t) => ({
190	    months: t.months,
191	    label: t.label,
192	    discountPercent: termDiscountPct(t.months, annualPct),
193	  }));
194	
195	  /* Add-on rates come from the same functions the charge path reads. A rate
196	     hardcoded next to a checkbox is how a display price and a charged price
197	     drift apart. */
198	  /* Families are built from the tiers that actually exist. A family with no
199	     active plan is not offered — the alternative is a card that leads to an
200	     empty tier list. Variants and the subdomain requirement come from the
201	     platform's own family schema, not from a list kept here. */
202	  // Leads the game grid, in this order, each badged "Popular" — the owner's
203	  // pick, not a computed ranking (no real play-count/order-volume signal
204	  // exists yet to rank by). `projectzomboid`/`sdtd` are the actual family
205	  // keys behind "Project Zomboid" / "7 Days to Die" (lib/games.ts
206	  // GAME_FAMILIES) — the display names aren't the lookup keys.
207	  const POPULAR_GAME_ORDER = ["minecraft", "rust", "valheim", "palworld", "projectzomboid", "terraria"];
208	  const gameFamilies: GameFamilyOption[] = (() => {
209	    const byFamily = new Map<string, typeof gamePlans>();
210	    for (const gp of gamePlans) {
211	      const list = byFamily.get(gp.gameFamily) ?? [];
212	      list.push(gp);
213	      byFamily.set(gp.gameFamily, list);
214	    }
215	    return [...byFamily.entries()].map(([family, tiers]) => {
216	      const schema = GAME_CONFIG_SCHEMAS[family];
217	      return {
218	        family,
219	        name: GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family,
220	        art: gameArt(family),
221	        variants: schema?.variants ?? [],
222	        defaultVariant: schema?.defaultVariant ?? "",
223	        genres: GAME_GENRES[family as keyof typeof GAME_GENRES] ?? [],
224	        /* Same source of truth quoteGameOrder (lib/game-order.ts) charges
225	           through — a second, hand-maintained "just minecraft" check here
226	           silently left every other hostname-connect family (ARK, the
227	           Source-engine titles, Satisfactory, Conan, 7 Days to Die,
228	           Enshrouded, and more) without a "Play address" field to fill in,
229	           so their orders could reach the payment step with no subdomain
230	           and no way to price. */
231	        needsSubdomain: family === "minecraft" || family === "bedrock"
232	          || HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily),
233	        /* Same lesson as needsSubdomain right above: a family's checkout-time
234	           required fields were never surfaced to the wizard at all, so an
235	           order for Valheim, CS2, Dragonwilds, Sunkenland, DST or Mordhau
236	           could reach Payment priced against an empty config and fail there
237	           with no field to fix it.
238	           NOT filtered by `field.phase` — that axis means "does changing this
239	           LATER need a redeploy" (FieldPhase is "deploy" | "live"), which has
240	           nothing to do with whether checkout should ask for it. Every field
241	           rides along here; the wizard shows `required` ones inline and folds
242	           the rest under a collapsed "Advanced settings" disclosure, since
243	           they all carry sensible defaults and are just as editable from the
244	           dashboard's Settings tab after purchase. */
245	        checkoutFields: schema?.fields ?? [],
246	        // Lead with the intro rate where one exists, same as every other
247	        // "from $X" price on this page — a tier's regular priceCents is its
248	        // RENEWAL rate post-grandfather-program, not what a new order pays.
249	        fromCents: Math.min(...tiers.map((t) => planIntroMonthlyCents(t) ?? t.priceCents)),
250	        popular: POPULAR_GAME_ORDER.includes(family),
251	        tiers: tiers.map((t) => ({
252	          id: t.id,
253	          name: t.name,
254	          ramMB: t.ramMB,
255	          cpuCores: t.cpuCores,
256	          diskGB: t.diskGB,
257	          slots: t.slots ?? null,
258	          monthlyCents: t.priceCents,
259	          termMonths: t.termMonths,
260	          // Same GRANDFATHER PROGRAM columns as Plan (lib/game-order.ts already
261	          // reads them at charge time) — `planIntroMonthlyCents` is generic
262	          // over any `{priceCents}` row, so this is the identical helper VPS
263	          // uses, not a second formula.
264	          introMonthlyCents: planIntroMonthlyCents(t),
265	          introRenewalMonthlyCents: planIntroMonthlyCents(t) !== null ? t.priceCents : null,
266	          introPercent: introBadgePercent(t.priceCents, planIntroMonthlyCents(t)),
267	        })),
268	      };
269	    }).sort((a, b) => {
270	      const pa = POPULAR_GAME_ORDER.indexOf(a.family);
271	      const pb = POPULAR_GAME_ORDER.indexOf(b.family);
272	      if (pa !== -1 || pb !== -1) return (pa === -1 ? 999 : pa) - (pb === -1 ? 999 : pb);
273	      return a.name.localeCompare(b.name);
274	    });
275	  })();
276	
277	  const hostingOptions: HostingPlanOption[] = hostingPlans.map((h) => ({
278	    id: h.id, name: h.name, tagline: h.tagline,
279	    diskGB: h.diskGB, maxSites: h.maxSites, maxDatabases: h.maxDatabases,
280	    bandwidthTB: h.bandwidthTB, mailboxes: h.mailboxes,
281	    freeMigration: h.freeMigration, featured: h.featured,
282	    monthlyCents: h.priceCents,
283	  }));
284	
285	  const emailOptions: EmailPlanOption[] = emailPlans.map((e) => ({
286	    id: e.id, name: e.name, mailboxes: e.mailboxes,
287	    storageGB: e.storageGB, monthlyCents: e.priceCents, termMonths: e.termMonths,
288	  }));
289	
290	  /* Hosting and email price through `termPriceCents` — the same helper their
291	     own charge paths use (lib/actions-hosting.ts, lib/actions-email-hosting.ts).
292	     Built as a matrix for the same reason as the VPS one: sending a rate and a
293	     discount percent would put the multiply back in the browser. */
294	  const hostingMatrix: Record<string, Record<number, number>> = {};
295	  // The real term total — `termPriceCents` unrounded-and-redivided — for the
296	  // checkout math. hostingMatrix above rounds THIS down to a per-month rate
297	  // for display ("$X/mo" labels), which is a real, separate rounding step:
298	  // re-multiplying that rounded rate back up by the term (as the checkout
299	  // total once did) silently drifts a cent or two from what the charge path
300	  // (lib/actions-hosting.ts's hostingChargeCents, same termPriceCents call)
301	  // actually bills. One rounding, at the total, shared with the charge path.
302	  const hostingTotalMatrix: Record<string, Record<number, number>> = {};
303	  // One month of the plan's own rate, credited when this customer still
304	  // qualifies — same shape as the VPS quote's `regularPlanCents - plan.priceCents`
305	  // (lib/order.ts), just carried alongside the matrix instead of computed by
306	  // a server round-trip. 0 (no credit) once first_month_free is off, already
307	  // claimed on this account/IP, or the plan changes and this needs recomputing.
308	  const hostingFirstMonthFreeCents: Record<string, number> = {};
309	  for (const h of hostingPlans) {
310	    hostingMatrix[h.id] = {};
311	    hostingTotalMatrix[h.id] = {};
312	    for (const t of VPS_TERMS) {
313	      const totalCents = termPriceCents(h.priceCents, t.months, annualPct);
314	      hostingTotalMatrix[h.id][t.months] = totalCents;
315	      hostingMatrix[h.id][t.months] = Math.round(totalCents / t.months);
316	    }
317	    hostingFirstMonthFreeCents[h.id] = hostingPromoEligible ? h.priceCents : 0;
318	  }
319	  const emailMatrix: Record<string, Record<number, number>> = {};
320	  const emailTotalMatrix: Record<string, Record<number, number>> = {};
321	  for (const e of emailPlans) {
322	    emailMatrix[e.id] = {};
323	    emailTotalMatrix[e.id] = {};
324	    for (const t of VPS_TERMS) {
325	      const totalCents = termPriceCents(e.priceCents, t.months, annualPct);
326	      emailTotalMatrix[e.id][t.months] = totalCents;
327	      emailMatrix[e.id][t.months] = Math.round(totalCents / t.months);
328	    }
329	  }
330	
331	  const addonOptions: AddonOption[] = [
332	    { key: "backup", name: "Backup Plus", note: "Longer retention, more restore points", icon: "archive", monthlyCents: backupCents, free: false },
333	    { key: "ip", name: "Dedicated IP", note: "An address of your own", icon: "nodes", monthlyCents: ipCents, free: false },
334	    { key: "malware", name: "Malware scanning", note: "Scheduled scans and alerts", icon: "shieldcheck", monthlyCents: 0, free: true },
335	    { key: "docker", name: "Docker pre-installed", note: "Ready for containers on first boot", icon: "docker", monthlyCents: 0, free: true },
336	  ];
337	
338	  // Only regions where a Node actually exists — the wizard can never sell a
339	  // location we cannot provision in. Computed once so the picker's list and
340	  // the resolved default agree on the exact same (deterministically-ordered)
341	  // set — see lib/nx/catalog.ts.
342	  const regions = regionsFrom(nodes);
343	
344	  return (
345	    // OrderProvider (components/nx/order.tsx) reads a marketing Deploy button's
346	    // selection off the URL via `useSearchParams()` (see lib/deploy-intent.ts) —
347	    // Next.js requires a Suspense boundary around any client component that
348	    // calls it, same as the old wizard's DeployHub did (see
349	    // app/dashboard/deploy/legacy-page.tsx.bak).
350	    <Suspense fallback={<div className="h-64 animate-pulse rounded-3xl border border-white/[0.06] bg-navy-900/40" />}>
351	    <DeployView
352	      cat={{
353	        plans: planOptions,
354	        games: gameFamilies,
355	        hosting: hostingOptions,
356	        email: emailOptions,
357	        hostingMatrix,
358	        hostingTotalMatrix,
359	        hostingFirstMonthFreeCents,
360	        emailMatrix,
361	        emailTotalMatrix,
362	        oses: osOptions,
363	        terms: termOptions,
364	        addons: addonOptions,
365	        regions,
366	        // Resolved server-side — see lib/nx/catalog.ts's defaultRegionKey doc
367	        // comment for why this is no longer `regions[0]`.
368	        defaultRegionKey: defaultRegionKey(regions, visitorCountry),
369	        diskPerGbCents,
370	        walletCents: user.balanceCents,
371	      }}
372	      priceMatrix={priceMatrix}
373	      hostingMatrix={hostingMatrix}
374	      emailMatrix={emailMatrix}
375	      firstName={user.name.split(" ")[0]}
376	      /* Which payment methods to OFFER. Read from the same predicates the
377	         charge paths use, so a method is never shown unless the platform can
378	         actually take money through it. In this sandbox all three are false by
379	         design, which is why the wallet is the only way to pay here. */
380	      methods={{
381	        card: stripeConfigured(),
382	        paypal: paypalConfigured(),
383	        crypto: coinbaseConfigured(),
384	      }}
385	      /* PayPal's PUBLIC client id. Safe to send to the browser — it is what the
386	         PayPal SDK script is keyed on and appears in every PayPal integration's
387	         page source. The SECRET stays on the server, where `createPayPalOrder`
388	         uses it. Null unless PayPal is actually configured, so the wizard can
389	         never mount the SDK against an empty id. */
390	      paypalClientId={paypalConfigured() ? process.env.PAYPAL_CLIENT_ID ?? null : null}
391	      isFirstTimeCustomer={isFirstTimeCustomer}
392	      exitIntentEnabled={exitIntentEnabled}
393	      fromCents={{
394	        // Same rule as every other "from $X" price on this page: lead with
395	        // the intro rate where one exists, not the post-grandfather-program
396	        // renewal rate — this tile is the first thing a new customer sees,
397	        // and it was still showing the higher number.
398	        vps: plans.length ? Math.min(...plans.map((p) => planIntroMonthlyCents(p) ?? p.priceCents)) : null,
399	        game: gamePlans.length ? Math.min(...gamePlans.map((g) => planIntroMonthlyCents(g) ?? g.priceCents)) : null,
400	        hosting: hostingPlans.length ? Math.min(...hostingPlans.map((h) => h.priceCents)) : null,
401	        email: emailPlans.length ? Math.min(...emailPlans.map((e) => e.priceCents)) : null,
402	        // No fixed plan row for domains — real price is a live per-TLD
403	        // registrar quote. 999 ($9.99) used to stand in here as a flat
404	        // guess; `null` renders this tile's existing "Pricing unavailable"
405	        // fallback instead of a number that isn't real.
406	        domains: null,
407	      }}
408	    />
409	    </Suspense>
410	  );
411	}
