147	  o: Order;
148	  set: <K extends keyof Order>(k: K, v: Order[K]) => void;
149	  chooseService: (k: ServiceKey) => void;
150	  chooseGame: (family: string) => void;
151	  game: GameFamilyOption | null;
152	  toggleAddon: (k: string) => void;
153	  reset: () => void;
154	  cat: Catalog;
155	  plan: PlanOption | null;
