169	/**
170	 * The full seed for a freshly-chosen service — same defaults `chooseService`
171	 * has always set (a complete, immediately-priceable order with only free
172	 * defaults ticked), pulled out as a pure function so `orderFromIntent` below
173	 * can start from the identical baseline before layering a marketing button's
174	 * specific selections on top. Takes the PREVIOUS order as `base` only so
175	 * fields the picker doesn't own (nothing today) would survive a re-seed —
176	 * `chooseService` and `orderFromIntent` both currently pass a full record in.
177	 */
178	function seedOrder(base: Order, cat: Catalog, k: ServiceKey): Order {
179	  const rec = cat.plans.find((p) => p.recommended) ?? cat.plans[0];
180	  return {
181	    ...base,
182	    service: k,
183	    planId: k === "vps" ? rec?.id ?? null : null,
184	    // NOT `cat.regions[0]` — with no explicit `orderBy` on the `Node` query
185	    // this fed the wizard's picker, `regions[0]` was whatever order Postgres
186	    // happened to return rows in, so a fresh order could seed a random
187	    // region. `defaultRegionKey` is resolved server-side, deterministically
188	    // (closest-to-visitor via geoip, else a fixed default) — see
189	    // lib/nx/catalog.ts.
190	    region: cat.defaultRegionKey ?? cat.regions[0]?.key ?? null,
191	    /* Must be a PLAIN_OS. Taking `oses[0]` picked whatever sorted first, and
192	       once the real catalogue landed that was Docker — an APPLICATION — so a
193	       fresh order defaulted to "operating system: Docker".
194	       Prefer the newest Ubuntu specifically — the most recognisable, most
195	       requested default — over whichever PLAIN_OS row happens to sort
196	       first alphabetically (AlmaLinux, before this). Falls back to the old
197	       "first PLAIN_OS" behavior if Ubuntu isn't in the catalogue at all. */
198	    osId: (
199	      cat.oses
200	        .filter((x) => x.category === "PLAIN_OS" && x.family === "ubuntu")
201	        .sort((a, b) => parseFloat(b.version || "0") - parseFloat(a.version || "0"))[0]
202	      ?? cat.oses.find((x) => x.category === "PLAIN_OS")
203	      ?? cat.oses[0]
204	    )?.id ?? null,
205	    termMonths: 1,
206	    /* A randomized "vps-xxxx" per order, never the same literal twice — was a
207	       hardcoded "web-01" until 2026-09-24, when production turned out to have
208	       7 unrelated customers all sharing that exact default (see
209	       lib/hostname.ts's doc comment for the resulting cross-customer
210	       data-exposure incident). Still only a STARTING point, not a uniqueness
211	       guarantee on its own: hostCheck below live-checks it (and whatever the
212	       customer edits it to) against the real DB as they type. */
213	    hostname: k === "vps" ? genDefaultVpsHostname() : "",
214	    serverName: k === "game" ? "My server" : "",
215	    addons: [],   // nothing that costs money is pre-selected
216	    diskGb: 0,
217	    /* A game order starts with NO family chosen — the picker is the next step,
218	       and pre-selecting one would put a product in the cart nobody asked for. */
219	    gameFamily: null, gamePlanId: null, gameVariant: null, subdomain: "",
220	    /* Hosting and email are bought against a DOMAIN, which only the customer
221	       can supply — there is no sensible default, so the field starts empty
222	       and the step is not "done" until they type one. */
223	    domain: "",
224	    subdomainLabel: "",
225	    /* Both seed their cheapest plan so the order is immediately priceable. */
226	    hostingPlanId: k === "hosting" ? (cat.hosting[0]?.id ?? null) : null,
227	    emailPlanId: k === "email" ? (cat.email[0]?.id ?? null) : null,
228	  };
229	}
