231	/** Reads a `DeployIntent` back off the URL, using the exact keys
232	 *  `lib/deploy-intent.ts`'s `deployHref` wrote — see that file for why each
233	 *  field has the query key it has. */
234	function parseIntent(sp: URLSearchParams): DeployIntent {
235	  const raw = (k: keyof DeployIntent) => sp.get(DEPLOY_PARAM[k]);
236	  const num = (k: keyof DeployIntent) => {
237	    const v = raw(k);
238	    if (!v) return undefined;
239	    const n = Number(v);
240	    return Number.isFinite(n) ? n : undefined;
241	  };
242	  const serviceRaw = raw("service");
243	  const service: DeployService | undefined =
244	    serviceRaw === "vps" || serviceRaw === "game" || serviceRaw === "hosting" || serviceRaw === "email"
245	      ? serviceRaw
246	      : undefined;
247	  const addonsRaw = raw("addons");
248	  return {
249	    service,
250	    planId: raw("planId") ?? undefined,
251	    termMonths: num("termMonths"),
252	    region: raw("region") ?? undefined,
253	    addons: addonsRaw ? addonsRaw.split(",").map((s) => s.trim()).filter(Boolean) : undefined,
254	    diskGb: num("diskGb"),
255	    gameFamily: raw("gameFamily") ?? undefined,
256	    gamePlanId: raw("gamePlanId") ?? undefined,
257	    gameVariant: raw("gameVariant") ?? undefined,
258	    players: num("players"),
259	    hostingPlanId: raw("hostingPlanId") ?? undefined,
260	    emailPlanId: raw("emailPlanId") ?? undefined,
261	    couponCode: raw("couponCode") ?? undefined,
262	  };
263	}
264	
265	/** The tier that best fits a desired headcount: the smallest slotted tier
266	 *  that still covers it, or — past the top of the ladder, or when the family
267	 *  has no slotted tiers at all — the single most expensive one, the closest
268	 *  real thing this family sells to "give me your biggest". Same judgment call
269	 *  GameLandingCombined's own player-count slider already makes, just applied
270	 *  against the LIVE catalogue instead of that page's illustrative fixture. */
271	function nearestTierBySlots(tiers: GameTier[], players: number): string | null {
272	  if (tiers.length === 0) return null;
273	  const slotted = tiers.filter((t): t is GameTier & { slots: number } => t.slots != null);
274	  const fits = slotted.filter((t) => t.slots >= players).sort((a, b) => a.slots - b.slots)[0];
275	  if (fits) return fits.id;
276	  const pool = slotted.length ? slotted : tiers;
277	  return [...pool].sort((a, b) => a.monthlyCents - b.monthlyCents).at(-1)?.id ?? null;
278	}
