280	/**
281	 * Materializes a `DeployIntent` into a real, catalogue-validated `Order` —
282	 * every id is checked against `cat` before it's used, so a stale or tampered
283	 * query string (an old link to a plan that's since been deactivated, say)
284	 * degrades to `seedOrder`'s normal defaults for whatever field didn't match,
285	 * never to a broken or half-filled order. Returns null when the URL carries
286	 * no recognised `product`, so the wizard opens on its ordinary empty first
287	 * step exactly as it always has.
288	 */
289	function orderFromIntent(cat: Catalog, intent: DeployIntent): Order | null {
290	  if (!intent.service) {
291	    // No specific service in the URL — but a coupon may still be attached
292	    // (a promo CTA that deliberately lands on the plain service picker
293	    // rather than defaulting into one product, e.g. lib/actions-promo-trial.ts's
294	    // ANY-service trial coupon — "works on any Game Server or Cloud VPS
295	    // plan" stops being true in practice if the button always drops the
296	    // customer into Game Servers specifically). Carry the coupon into the
297	    // ordinary empty first step instead of dropping it entirely.
298	    return intent.couponCode ? { ...EMPTY, couponCode: intent.couponCode } : null;
299	  }
300	  const o = seedOrder(EMPTY, cat, intent.service);
301	  // Applied regardless of which service branch runs below — a coupon covering
302	  // "any VPS or Game Server" (see lib/promo-trial.ts) isn't service-specific,
303	  // it just needs a real order to attach to.
304	  if (intent.couponCode) o.couponCode = intent.couponCode;
305	
306	  const term = intent.termMonths;
307	  if (term != null && cat.terms.some((t) => t.months === term)) o.termMonths = term;
308	
309	  // A region is not VPS-specific — game orders carry one too (`o.region`
310	  // gates the wizard's Region step for both). This used to live inside the
311	  // `vps`-only branch below, so a marketing page's "closest region" choice
312	  // (e.g. a game's own region picker, or `?region=fsn1` on a deploy link)
313	  // was read off the URL, matched against the real catalogue, and then
314	  // silently thrown away the moment `intent.service === "game"` — the
315	  // customer picked Germany on the marketing site and landed back on
316	  // whatever `seedOrder` defaulted to. Applied once, before the
317	  // per-service branches, so both paths get it.
318	  if (intent.region && cat.regions.some((r) => r.key === intent.region)) o.region = intent.region;
319	
320	  if (intent.service === "vps") {
321	    if (intent.planId && cat.plans.some((p) => p.id === intent.planId)) o.planId = intent.planId;
322	    if (intent.addons?.length) {
323	      const valid = new Set<string>(cat.addons.map((a) => a.key));
324	      const picked = intent.addons.filter((a) => valid.has(a));
325	      if (picked.length) o.addons = picked;
326	    }
327	    if (intent.diskGb != null && intent.diskGb >= 0) o.diskGb = Math.round(intent.diskGb);
328	  }
329	
330	  if (intent.service === "game") {
331	    const g = intent.gameFamily ? cat.games.find((x) => x.family === intent.gameFamily) : null;
332	    if (g) {
333	      o.gameFamily = g.family;
334	      const exact = intent.gamePlanId ? g.tiers.find((t) => t.id === intent.gamePlanId) : null;
335	      o.gamePlanId =
336	        exact?.id
337	        ?? (intent.players && intent.players > 0 ? nearestTierBySlots(g.tiers, intent.players) : null)
338	        ?? [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0]?.id
339	        ?? null;
340	      o.gameVariant =
341	        intent.gameVariant && g.variants.some((v) => v.id === intent.gameVariant)
342	          ? intent.gameVariant
343	          : g.defaultVariant;
344	    }
345	  }
346	
347	  if (intent.service === "hosting" && intent.hostingPlanId && cat.hosting.some((h) => h.id === intent.hostingPlanId)) {
348	    o.hostingPlanId = intent.hostingPlanId;
349	  }
350	
351	  if (intent.service === "email" && intent.emailPlanId && cat.email.some((e) => e.id === intent.emailPlanId)) {
352	    o.emailPlanId = intent.emailPlanId;
353	  }
354	
355	  return o;
356	}
