361	export function OrderProvider({ cat, children }: { cat: Catalog; children: React.ReactNode }) {
362	  // Read once, on mount: a marketing "Deploy" button's selection, carried here
363	  // via `/dashboard/deploy?product=...` (see lib/deploy-intent.ts) — including
364	  // unchanged across a login/signup detour, since that's just the existing
365	  // `?next=` convention carrying this same query string through (see
366	  // lib/safe-next.ts, app/login/page.tsx, app/dashboard/layout.tsx).
367	  // `useSearchParams()` needs this component under a Suspense boundary, which
368	  // app/dashboard/deploy/page.tsx provides around <DeployView>.
369	  const searchParams = useSearchParams();
370	  const [o, setO] = useState<Order>(() => orderFromIntent(cat, parseIntent(searchParams)) ?? EMPTY);
371	  const [price, setPrice] = useState<CartPrice>(null);
372	  const [pricing, setPricing] = useState(false);
373	  const [priceError, setPriceError] = useState<string | null>(null);
374	  const [hostCheck, setHostCheck] = useState<AvailabilityCheck>({ status: "idle" });
375	
376	  const set = useCallback(<K extends keyof Order>(k: K, v: Order[K]) => {
377	    setO((p) => ({ ...p, [k]: v }));
378	  }, []);
379	
380	  const chooseService = useCallback((k: ServiceKey) => {
381	    // Re-clicking the service tile that's already active must be a no-op —
382	    // this used to unconditionally reseed (fresh plan/term/hostname/addons),
383	    // so a customer who'd already configured VPS and tapped the "Cloud VPS"
384	    // tile again (e.g. from the rail, or a stray double-tap) lost everything
385	    // they'd picked below. Returning the SAME object (not a shallow copy)
386	    // also skips the reseed effects that key off a new `o` reference.
387	    setO((p) => (p.service === k ? p : seedOrder(p, cat, k)));
388	  }, [cat]);
389	
390	  /* Choosing a family seeds its cheapest tier and its default loader, so the
391	     order is immediately priceable; the customer changes what they care about. */
392	  const chooseGame = useCallback((family: string) => {
393	    // Same idempotency as chooseService above, one level down: re-picking the
394	    // family that's already selected must not reset the tier/variant/config
395	    // the customer already chose on the Server step back to the cheapest
396	    // tier and empty config.
397	    setO((p) => {
398	      if (p.gameFamily === family) return p;
399	      const g = cat.games.find((x) => x.family === family);
400	      if (!g) return p;
401	      const cheapest = [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0];
402	      return {
403	        ...p,
404	        gameFamily: family,
405	        gamePlanId: cheapest?.id ?? null,
406	        gameVariant: g.defaultVariant,
407	        subdomain: "",
408	        // A previous game's field values (e.g. Valheim's SERVER_PASS) must never
409	        // leak into a different family's config — keys rarely collide, but when
410	        // they do (two families both using SERVER_PASS) a stale value would
411	        // silently carry over instead of the customer setting their own.
412	        gameConfig: {},
413	      };
414	    });
415	  }, [cat]);
416	
417	  const toggleAddon = useCallback((k: string) => {
418	    setO((p) => ({
419	      ...p,
420	      addons: p.addons.includes(k) ? p.addons.filter((x) => x !== k) : [...p.addons, k],
421	    }));
422	  }, []);
423	
424	  const plan = useMemo(() => cat.plans.find((p) => p.id === o.planId) ?? null, [cat.plans, o.planId]);
425	  const game = useMemo(
426	    () => cat.games.find((g) => g.family === o.gameFamily) ?? null,
427	    [cat.games, o.gameFamily]
428	  );
429	
430	  /* ── live pricing ────────────────────────────────────────────────────────
431	     Debounced, and guarded against out-of-order replies: dragging the disk
432	     slider fires many quotes and they can come back in any order, so a stale
433	     one must never overwrite a newer one. Without the sequence check the cart
434	     can settle on the price of a selection the customer already moved past. */
435	  const seq = useRef(0);
436	  useEffect(() => {
437	    /* One effect, two products. Each asks ITS OWN server-side quote — the VPS
438	       one through `orderQuote`, the game one through `gameOrderQuote` — because
439	       the two price completely differently (a game tier is a flat term price;
440	       a VPS accrues add-ons, disk and a dedicated IP). Nothing here does
441	       arithmetic; it only chooses which server function to ask. */
442	    const vpsReady = o.service === "vps" && o.planId && o.osId;
443	    /* Minecraft cannot be quoted without its play subdomain: `quoteGameOrder`
444	       claims-checks the name, so asking before the customer has typed one comes
445	       back an error, and the wizard rendered that as a bare "—" total with the
446	       explanation buried in the cart. Wait for the field the family actually
447	       requires, and let the bar say what is missing instead. */
448	    const gameNeedsSubdomain = o.service === "game" && !!game?.needsSubdomain;
449	    const gameReady = o.service === "game" && o.gamePlanId
450	      && (!gameNeedsSubdomain || o.subdomain.trim().length > 2);
451	
452	    /* Hosting and email price from the server-built matrix the page handed down
453	       (termPriceCents — the same helper their charge paths use), so there is no
454	       round-trip to make and nothing for this effect to await. Still not derived
455	       HERE: the browser looks a value up, it does not compute one. */
456	    /* A domain is priced per YEAR by the registrar, already carrying our markup
457	       — there is no plan and no term ladder. The number came back from
458	       `searchDomains`; multiplying it by the years is the one arithmetic this
459	       file does, and it is the same multiplication `purchaseDomain` performs. */
460	    if (o.service === "domains") {
461	      if (o.domainPriceCents === null) { setPrice(null); setPriceError(null); return; }
462	      const total = o.domainPriceCents * o.years;
463	      setPricing(false);
464	      setPriceError(null);
465	      setPrice({
466	        totalCents: total, months: o.years * 12, regularPlanCents: total,
467	        promoName: "", promoCreditCents: 0,
468	        couponLabel: null, couponDiscountCents: 0, couponError: null,
469	        introRenewalMonthly: null,
470	        renewalTotalCents: total,
471	        // Domains are excluded from the Creator Partner Program at every tier.
472	        partnerDiscountCents: 0, partnerDiscountPercent: 0, partnerDiscountTier: "NONE", partnerName: null,
473	      });
474	      return;
475	    }
476	
477	    // Read the real term total directly — NOT the *Matrix per-month rate
478	    // multiplied back up. That rate is already rounded once (for its own
479	    // "$X/mo" display), so re-multiplying it by the term double-rounds and
480	    // drifts a cent or two from what the charge path actually bills (see
