/* ── the step marks above the wizard ────────────────────────────────────
   Floating, no panel behind them: done is a filled mint disc with a tick,
   the current step is a filled brand disc with a ring, the rest are hollow.
   The connector fills as you advance. */
export function StepMarks({ steps, i, go }: {
  steps: { key: string; label: string; done: boolean; live: boolean }[];
  i: number; go: (n: number) => void;
}) {
  return (
    /* `overflow-x-auto` was already here, but `justify-center` on a flex row
       that overflows is a well-known trap: the browser centers the content
       BEFORE laying out the scrollable area, so the steps before whatever
       lands at `scrollLeft: 0` sit at a negative x-offset — reachable by
       scrolling right from the middle, but `scrollLeft` can never go
       negative, so the earliest step(s) were permanently unreachable, not
       just visually cramped. `justify-start` below the phone breakpoint
       gives the scroll area a real, reachable 0 at the actual first step;
