 * Takes the ALREADY-RETRIEVED session (fulfil-checkout has it) rather than an id,
 * so the one session read is shared. The session from `retrieveCheckoutSession`
 * is unexpanded, so `payment_intent` is an id string — we retrieve the intent with
 * the payment method expanded.
 *
 * NEVER throws: the money has already moved and been fulfilled by the time this
 * runs, so a failure here must be inert. Writes the card mirror plus a
 * best-effort `card.saved` audit row (its own failure is swallowed, never
 * escalated — the mirror write is what matters). Returns `{ card }` on success
 * or `{ error }` otherwise.
 */
export async function saveCardFromPaymentSession(
  session: Stripe.Checkout.Session,
  userId: string,
): Promise<{ card?: SavedCard; error?: string }> {
  // Every caller (9 fulfilment paths — order, game order, hosting, email,
  // domain, resize, disk-expand, dedicated IP, plus the generic dispatch)
  // awaits this and then discards a returned `{error}` inside its own
  // `catch { /* best-effort */ }`, so a failure here was completely silent —
  // fulfilment succeeded, no card got saved, and nothing anywhere recorded
  // why. Found live 2026-09-24: 8 real paying customers had a successful
  // Stripe charge and zero saved card, each silently defaulting to the
  // faster "no card on file" dunning/suspend timeline despite having paid by
  // card. Every early return below now logs with the userId, so a repeat is
  // at least visible in the same place the existing catch already logged to
  // (this function's own console.error), not just a return value nobody read.
  if (!stripeConfigured()) {
    console.error(`[cards] could not save card for user ${userId}: Stripe not configured`);
    return { error: "Card payments are not configured." };
  }
  try {
    const piRef = session.payment_intent;
    const piId = typeof piRef === "string" ? piRef : (piRef?.id ?? null);
    const customerId =
      typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
    if (!piId || !customerId) {
      console.error(
        `[cards] could not save card for user ${userId}: no payment_intent/customer on session ${session.id ?? "?"}`,
      );
      return { error: "No payment intent / customer on the session." };
    }

    const pi = await stripe().paymentIntents.retrieve(piId, { expand: ["payment_method"] });
    const pmRef = pi.payment_method;
    const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
    if (!pmId) {
      console.error(`[cards] could not save card for user ${userId}: no payment_method on ${piId}`);
      return { error: "No payment method on the payment intent." };
    }
    // Expanded above, so usually already the object; fall back to a retrieve.
    const pm: Stripe.PaymentMethod =
      pmRef && typeof pmRef !== "string" ? pmRef : await stripe().paymentMethods.retrieve(pmId);

    // Make it the customer's default — best-effort, exactly like the setup version;
    // our own `stripePaymentMethodId` is the source of truth for charging.
    await stripe()
      .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
      .catch(() => {
        /* non-fatal */
      });
    await persistCard(userId, customerId, pm);
    // Found alongside the 2026-09-24 incident this function's own comment
    // documents: not just a silent-failure problem, a silent-SUCCESS one too.
    // A card saved through one of the 9 payment flows this feeds (wallet
    // top-up included) wrote no audit trail at all — `finalizeCardSetup`
    // (the dedicated "add a card" flow) logs `card.saved`, but a card
    // attached as a SIDE EFFECT of paying for something never did, so an
    // investigation into "where did this customer's card come from / go"
    // had no record to find for the majority of real card saves. Detail
    // says "via payment" specifically so it reads differently from the
    // setup-flow's own `card.saved` rows in the same log.
    await db.auditLog
      .create({
        data: {
          userId,
          action: "card.saved",
          detail: `${cardDisplayLabel({
            brand: pm.card?.brand ?? null,
            last4: pm.card?.last4 ?? null,
            expMonth: pm.card?.exp_month ?? null,
            expYear: pm.card?.exp_year ?? null,
          })} (via payment)`,
        },
      })
      .catch((e) => console.error(`[cards] card.saved audit log failed for ${userId}`, e));
    return {
      card: {
        brand: pm.card?.brand ?? null,
        last4: pm.card?.last4 ?? null,
        expMonth: pm.card?.exp_month ?? null,
        expYear: pm.card?.exp_year ?? null,
      },
    };
  } catch (e) {
    console.error(`[cards] could not record card from payment session for user ${userId}`, e);
    return { error: "We couldn't record the card from this payment." };
  }
}

