/* ── type ─────────────────────────────────────────────────────────────── */
/* Numbers stay in the proportional sans and never carry a gradient — a
   gradient inside a numeral is the single cheapest-looking thing in the set. */
.num { color: var(--color-tx); font-weight: 800; letter-spacing: -0.038em;
       font-variant-numeric: tabular-nums; line-height: 1.04; }
.nx-label { font-size: 11px; font-weight: 600; letter-spacing: 0.05em; color: var(--color-tx-faint); }

/* ── controls ─────────────────────────────────────────────────────────── */
/* The deploy CTA, carried over from the live portal's `.btn-deploy`: a pill on
   a four-stop gradient that slides across on hover, a one-shot shimmer sweep,
   a 1px lift and an arrow nudge. Stops are Nexion's own, the motion is the
   original's. Reduced motion gets the static gradient. */

.btn {
  position: relative; overflow: hidden;
  display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  height: 44px; padding: 0 22px; border-radius: 999px;
  font-size: 14px; font-weight: 750; color: #fff; white-space: nowrap;
  background-image: linear-gradient(110deg, #6f2ee0, #1a55cf, #2bb6d6, #6f2ee0);
  background-size: 220% 100%;
  background-position: 0% 0;
  box-shadow: 0 6px 18px -8px rgba(88,60,255,0.34), inset 0 1px 0 0 rgba(255,255,255,0.14);
  transition: transform .2s ease, box-shadow .2s ease, background-position .6s ease;
}
.btn::before {
  content: ""; position: absolute; inset-block: 0; left: 0; width: 60%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.26), transparent);
  transform: translateX(-130%) skewX(-12deg);
  pointer-events: none;
}
.btn:hover {
  transform: translateY(-1px);
  background-position: 100% 0;
  box-shadow: 0 9px 24px -8px rgba(88,60,255,0.44), inset 0 1px 0 0 rgba(255,255,255,0.19);
}
.btn:hover::before { animation: btn-sweep .75s ease; }

/* Select control matching `.field`. The option LIST is painted by the OS, so
   it needs its own background — without it a dark page opens a white
   dropdown, which is the one piece of chrome a dark theme cannot restyle
   from the outside. */
.nxsel {
  height: 38px; padding: 0 12px; border-radius: 10px; cursor: pointer;
  border: 1px solid var(--color-rim-hi); background: var(--color-well);
  color: #fff; font-size: 12.5px; font-weight: 600; font-family: inherit;
  min-width: 150px;
}
.nxsel:focus { outline: none; border-color: #2f7eef; }
.nxsel > option { background: #04214f; color: #fff; }

/* A required field the customer tried to walk past. The shake is the whole
   point: a static red border on a field that was ALREADY on screen reads as
   decoration, whereas movement draws the eye to the thing blocking them.
   Keyed re-render restarts it on every attempt, so a second Next shakes
   again rather than sitting still because the class never changed. */

.field-bad {
  border-color: rgba(239,66,108,0.62) !important;
  box-shadow: 0 0 0 3px rgba(239,66,108,0.12), 0 0 18px -8px rgba(239,66,108,0.5);
  animation: nx-shake .42s cubic-bezier(.36,.07,.19,.97) both;
}
@media (prefers-reduced-motion: reduce) {
  /* The border and ring still mark it; only the movement goes. */
  .field-bad { animation: none; }
}

/* The pay CTA — cyan to warm pink instead of the violet/blue of a normal
   primary button, so the one control that takes money reads as its own thing.
   Everything about the MOTION is `.btn`'s and untouched: the 220% background
   that slides on hover, the lift, the shimmer sweep. Only the hues and the
   shadow tint change, the shadow following the pink so the glow does not stay
   violet under a pink button.

   Deliberately a modifier rather than an edit to `.btn`, which is every
   primary button in the portal — "Open the panel", "Continue to your server",
   and the rest. Promote it into `.btn` if the whole set should change. */
.btn-pay {
  background-image: linear-gradient(110deg, #14c5e4, #56b8dd, #ff7eb0, #ff6f91, #14c5e4);
  box-shadow: 0 6px 18px -8px rgba(255,111,145,0.38), inset 0 1px 0 0 rgba(255,255,255,0.16);
}
.btn-pay:hover {
  box-shadow: 0 9px 24px -8px rgba(255,111,145,0.5), inset 0 1px 0 0 rgba(255,255,255,0.2);
}
.btn:active { transform: translateY(0); }
.btn:disabled { transform: none; box-shadow: none; cursor: not-allowed; }
.btn:disabled::before { animation: none; }
.arw { transition: transform .25s ease; }
.btn:hover .arw { transform: translateX(3px); }
@media (prefers-reduced-motion: reduce) {
  .btn, .btn:hover { transition: none; transform: none; }
  .btn:hover::before { animation: none; }
  .btn:hover .arw { transform: none; }
  .deck, .deck-track { transition: none !important; }
}
/* A tone chip is a single-hue object: fill, border, mark and label all one
   colour. This is the rule the whole vector switch existed to make possible
   (the sprite put a teal shieldcheck on the violet Admin chip). */
.chip-tone .nx-ico { color: inherit; filter: none; }

/* Solid/gradient buttons carry their own text colour — a violet mark on a
   violet gradient disappears. */
.btn-primary .nx-ico,
.btn-danger .nx-ico,
.btn-deploy .nx-ico,
.badge .nx-ico { color: inherit; filter: none; }

/* Inside a filled input/field the mark is chrome, not decoration: it should
   sit quietly with the placeholder rather than glow next to typed text. */
.field .nx-ico { color: var(--color-tx-faint); filter: none; }

