/* ── intro renewal note ─────────────────────────────────────────────────
   The one line that stands in for the removed discount badge on every
   intro-priced card (VPS plans here, game tiers in DeployView): plain, small,
   not a pill — "First month, then $6.49/mo". `renewalCents` is the plan's
   regular monthly rate, the same figure lib/order.ts quotes as
   `introRenewalMonthly` and lib/renewal-charge.ts renews at. */
export function IntroRenewalNote({ renewalCents, isMonthly, className = "" }: {
  renewalCents: number; isMonthly: boolean; className?: string;
}) {
  return (
    <span className={"text-[11px] text-tx-faint " + className}>
      First {isMonthly ? "month" : "term"}, then {money(renewalCents)}/mo
    </span>
  );
}

/* ── plan card ────────────────────────────────────────────────────────── */
/* The card PRINTS a price, it does not work one out.
   `effectiveMonthlyCents` arrives already discounted for the selected term, from
   the same basis the charge path uses. The sandbox version multiplied a rate by
   a term discount right here, which is a second pricing formula — and the moment
   it disagrees with `orderQuote` the customer sees one number and is charged
   another. */
export function PlanCard({ p, blurb, on, onClick, isMonthly = true }: {
  p: PlanOption; blurb?: string; on: boolean; onClick: () => void;
  /** Selected billing term, monthly or not — decides whether the renewal line
   *  says "first month" or "first term" (a longer term's intro discount covers
   *  the WHOLE first term, not one month of it). */
  isMonthly?: boolean;
}) {
  const eff = p.effectiveMonthlyCents;
  const discounted = p.effectiveMonthlyCents < p.monthlyCents;
  /* The headline is the SMALLEST real price a new customer can pay — the
     intro rate when the plan carries one. No discount badge (owner's call,
     2026-09-27: the orange "X% OFF · FIRST MONTH" pill is gone from every
     plan card in the wizard); what keeps a bare intro figure honest instead
     is the small, plain renewal line directly under it — the card never
     states an intro rate without saying what it renews at. The Order summary
     step repeats the same renewal figure next to the total. */
  const hasIntro = p.introMonthlyCents !== null && p.introRenewalMonthlyCents !== null;
  const headlineCents = hasIntro ? p.introMonthlyCents! : eff;
  return (
    <Pick on={on} onClick={onClick} className="relative flex flex-col gap-3 p-3.5">
      {p.recommended && (
        <span className="absolute -top-[9px] left-3.5 rounded-full bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)]
                         px-2.5 py-[3px] text-[10px] font-extrabold uppercase tracking-[0.07em] text-white
                         shadow-[0_0_13px_-8px_rgba(88,60,255,0.5)]">
          Most popular
        </span>
      )}
      <span className="flex flex-col gap-0.5">
        <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">{p.name}</span>
        {/* Who it is FOR. The specs are already listed below, so repeating them
            here spent the one line that could say something else. */}
        <span className="text-[11.5px] text-tx-faint">{blurb ?? `${p.cpuCores} vCPU · ${p.ramMB / 1024} GB RAM`}</span>
      </span>

      <span className="flex items-baseline gap-1.5">
        <span className="num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[25px] text-transparent">
          {money(headlineCents)}
        </span>
        <span className="text-[11.5px] text-tx-dim">/mo</span>
      </span>
      {hasIntro ? (
        <IntroRenewalNote renewalCents={p.introRenewalMonthlyCents!} isMonthly={isMonthly} className="-mt-2" />
      ) : discounted && (
        <span className="-mt-2 text-[11px] text-tx-faint">
          {money(p.monthlyCents)}/mo billed monthly
        </span>
      )}

      <ul className="flex flex-col gap-1.5">
        {[
          { icon: "cpu", text: `${p.cpuCores} vCPU` },
          { icon: "ram", text: `${p.ramMB / 1024} GB RAM` },
          { icon: "database", text: `${p.diskGB} GB NVMe` },
          { icon: "nodes", text: `${p.bandwidthTB} TB transfer` },
        ].map((sp) => (
          <li key={sp.text} className="flex items-center gap-2 text-[12px] text-tx-body">
            <Icon name={sp.icon} size={14} className="flex-none opacity-85" />{sp.text}
          </li>

