"use client";

import { useEffect, useState } from "react";

/* Real, per-visitor latency to each deploy region, measured in THIS browser.
 *
 * Nothing here is estimated. For every region that has a probe URL (a small
 * endpoint physically served from that region — lib/region-probe.ts) the
 * browser times real round trips: one warm-up request first, so DNS, TCP, TLS
 * and (in dev) route compilation are not counted, then SAMPLES timed requests,
 * and the card shows their MEDIAN — robust to the odd slow sample, and still a
 * figure this visitor actually got. A region with no probe URL, or whose every
 * sample failed, reports "none" and the card shows a neutral "— ms".
 *
 * Regions are probed one after another, never in parallel, so two probes never
 * compete for the same connection and inflate each other. Cross-origin probes
 * go out `no-cors` (an opaque response is still a completed round trip, and a
 * static file then needs no CORS headers) with no credentials; `no-store`
 * keeps any cache from answering in place of the region.
 *
 * Runs once per page view, and only once `enabled` (the region step is on
 * screen) — not for every visitor who opens the wizard and never gets there. */

export type LatencyState = { status: "measuring" } | { status: "ok"; ms: number } | { status: "none" };

const SAMPLES = 5;
const TIMEOUT_MS = 3000;

async function timeOnce(url: string, crossOrigin: boolean, n: number): Promise<number | null> {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), TIMEOUT_MS);
  const sep = url.includes("?") ? "&" : "?";
  const target = `${url}${sep}rtt=${n}-${Date.now()}`;
  const t0 = performance.now();
  try {
    const res = await fetch(target, {
      cache: "no-store",
      signal: ctl.signal,
      ...(crossOrigin ? { mode: "no-cors" as const, credentials: "omit" as const } : {}),
    });
    // Same-origin: wait for the (tiny) body too, so the timing covers the
    // complete response. An opaque no-cors response has no readable body.
    if (!crossOrigin) {
      if (!res.ok) return null;
      await res.arrayBuffer();
    }
    return performance.now() - t0;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
