    return null;
  }
  await timeOnce(url, crossOrigin, 0); // warm-up, discarded
  const got: number[] = [];
  for (let i = 1; i <= SAMPLES; i++) {
    const ms = await timeOnce(url, crossOrigin, i);
    if (ms !== null) got.push(ms);
  }
  if (!got.length) return null;
  got.sort((a, b) => a - b);
  const mid = Math.floor(got.length / 2);
  const median = got.length % 2 ? got[mid] : (got[mid - 1] + got[mid]) / 2;
  return Math.max(1, Math.round(median));
}

export function useRegionLatency(
  regions: { key: string; probeUrl?: string | null }[],
  enabled: boolean,
): Record<string, LatencyState> {
  const [state, setState] = useState<Record<string, LatencyState>>(() =>
    Object.fromEntries(regions.map((r) => [r.key, r.probeUrl ? { status: "measuring" } : { status: "none" }])),
  );
  const [started, setStarted] = useState(false);

  useEffect(() => {
    if (!enabled || started) return;
    setStarted(true);
    let cancelled = false;
    (async () => {
      for (const r of regions) {
        if (cancelled) return;
        if (!r.probeUrl) continue;
        const ms = await measureRtt(r.probeUrl);
        if (cancelled) return;
