export function useRegionLatency(
  regions: { key: string; probeUrl?: string | null }[],
  enabled: boolean,
): Record<string, LatencyState> {
  const [state, setState] = useState<Record<string, LatencyState>>(() =>
    Object.fromEntries(regions.map((r) => [r.key, r.probeUrl ? { status: "measuring" } : { status: "none" }])),
  );
  /* Latched: once the region step has been on screen, the measurement runs
     to completion even if the customer moves on mid-probe (it is a handful of
     tiny requests), and leaving and coming back does not re-probe. The
     measuring effect below therefore depends on `armed` alone, which only
     ever flips false -> true, so its cleanup runs on unmount only. */
  const [armed, setArmed] = useState(false);
  useEffect(() => { if (enabled) setArmed(true); }, [enabled]);

  useEffect(() => {
    if (!armed) return;
    let cancelled = false;
    (async () => {
      for (const r of regions) {
        if (cancelled) return;
        if (!r.probeUrl) continue;
        const ms = await measureRtt(r.probeUrl);
        if (cancelled) return;
        setState((s) => ({ ...s, [r.key]: ms === null ? { status: "none" } : { status: "ok", ms } }));
      }
    })();
    return () => { cancelled = true; };
    // `regions` is the server-built catalogue list, stable for the page's life.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [armed]);

  return state;
}

