export async function quoteOrder(intent: OrderIntent): Promise<QuoteResult> {
  const user = await requireUser();
  try {
    const q = await orderQuote(intent, { userId: user.id });
    const taxCents = 0; // orderQuote returns net; tax is applied on the charge leg.
    // Catalog-level checks (service/plan/term/dates/global cap) already ran
    // inside orderQuote; this adds the two ACCOUNT-level ones it can't see —
    // see couponAccountEligibilityError's own doc comment for why the preview
    // needs this too, not just the real reservation at pay time.
    let couponDiscountCents = q.couponDiscountCents ?? 0;
    let couponLabel: string | null = q.couponLabel ?? null;
    let couponError: string | null = q.couponError ?? null;
    if (q.couponId && couponDiscountCents > 0) {
      const ineligible = await couponAccountEligibilityError({
        userId: user.id,
        firstTimeOnly: q.couponFirstTimeOnly,
        excludeActiveCustomers: q.couponExcludeActiveCustomers,
      });
      if (ineligible) {
        couponDiscountCents = 0;
        couponLabel = null;
        couponError = ineligible;
      }
    }
    // q.chargeCents already has q.couponDiscountCents subtracted once; add it
    // back to recover the full (undiscounted) price, then subtract whatever
    // the corrected (possibly now-zeroed) discount actually is.
    const chargeCents = q.chargeCents + (q.couponDiscountCents ?? 0) - couponDiscountCents;
    return {
      ok: true,
      chargeCents,
      taxCents,
      totalCents: chargeCents + taxCents,
      months: q.term.months,
      regularPlanCents: q.regularPlanCents,
      promoCreditCents: q.promoCreditCents ?? 0,
      /* STRICT: the promo is named only when it actually put money back on THIS
         order. `discountPercent` is a property of the promo, not of this quote —
         first-month-free carries one while applying to hosting only, which is
         how a VPS order ended up captioned "First month free" while being
         charged in full. A percentage promo that really did apply shows up as
         chargeCents below regularPlanCents, and the struck-through "was" price
         already tells that story. */
      promoName: (q.promoCreditCents ?? 0) > 0 ? q.promo?.name ?? "" : "",
      promoPercent: q.promo?.discountPercent ?? 0,
      couponLabel,
      couponDiscountCents,
      couponError,
      extraDiskCents: q.extraDiskCents ?? 0,
      backupCents: q.backupCents ?? 0,
      introMonthlyCents: q.introMonthlyCents || null,
      // Only meaningful alongside an intro rate; without one it is just the
      // regular price restated in amber, which reads as a warning.
      introRenewalMonthly: q.introMonthlyCents ? q.introRenewalMonthly ?? null : null,
      renewalTotalCents: q.renewalTotalCents ?? q.chargeCents,
      partnerDiscountCents: q.partnerDiscountCents ?? 0,
      partnerDiscountPercent: q.partnerDiscountPercent ?? 0,
