"use client";
// DEV-ONLY HARNESS — never committed. Mounts the wizard's real NxCardFields against a
// real TEST-MODE Checkout Session, so the saved-card chooser and a new-card payment can be
// exercised end to end without a portal login.
import { useEffect, useRef, useState } from "react";
import { NxCardFields } from "@/components/nx/NxCardFields";

export default function CardHarness() {
  const [s, setS] = useState<{ clientSecret: string; publishableKey: string; sessionId: string } | null>(null);
  const confirm = useRef<(() => Promise<void>) | null>(null);
  const [can, setCan] = useState(false);
  const [busy, setBusy] = useState<string>("");
  useEffect(() => {
    const q = new URLSearchParams(location.search);
    fetch("/zz-harness/api", { method: "POST", body: JSON.stringify({ kind: "session", arg: { withCard: q.get("card") !== "0", filters: q.get("filters") } }) })
      .then((r) => r.json()).then(setS);
  }, []);
  return (
    <div className="nx-shell-root min-h-screen bg-[var(--color-bg)] p-8">
      <div className="card mx-auto max-w-[620px] p-4">
        <div id="sid">{s?.sessionId}</div>
        {s && <NxCardFields clientSecret={s.clientSecret} publishableKey={s.publishableKey}
                 onConfirmReady={(fn) => { confirm.current = fn; setCan(!!fn); }}
                 onBusy={(b, e) => setBusy(b ? "busy" : e ?? "")} />}
        <button id="pay" type="button" disabled={!can} onClick={() => void confirm.current?.()}
                className="btn-deploy mt-4 h-[46px] w-full justify-center text-[13.5px] font-bold disabled:opacity-45">
          Pay $11.69 and deploy <span className="dep-arrow">→</span>
        </button>
        <div id="busy">{busy}</div>
      </div>
    </div>
  );
}
