      <div className="card mx-auto max-w-[620px] p-4">
        <div id="sid">{s?.sessionId}</div>
        {s && <NxCardFields clientSecret={s.clientSecret} publishableKey={s.publishableKey}
                 onConfirmReady={(fn) => { confirm.current = fn; setCan(!!fn); }}
                 onBusy={(b, e) => setBusy(b ? "busy" : e ?? "")} />}
        <button id="pay" type="button" disabled={!can} onClick={() => void confirm.current?.()}
                className="btn-deploy mt-4 h-[46px] w-full justify-center text-[13.5px] font-bold disabled:opacity-45">
          Pay $11.69 and deploy <span className="dep-arrow">→</span>
        </button>
        <div id="busy">{busy}</div>
      </div>
    </div>
  );
}
